describe('Notification Navigation', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.viewport(1280, 720);
  });

  it('should navigate to relevant content when clicking a notification', () => {
    cy.get('[data-testid="notification-bell"]').click();
    cy.get('[data-testid="notification-list"]').should('be.visible');

    cy.get('[data-testid="notification-item"]').first().click();

    cy.url().should('include', '/content');
    cy.get('[data-testid="content-page"]').should('be.visible');
    cy.get('h1').should('contain', 'Content');
  });

  it('should navigate to correct content for different notification types', () => {
    cy.get('[data-testid="notification-bell"]').click();
    cy.get('[data-testid="notification-list"]').should('be.visible');

    cy.get('[data-testid="notification-item"]').contains('Message').click();
    cy.url().should('include', '/messages');
    cy.get('[data-testid="messages-page"]').should('be.visible');
  });

  it('should handle notification click when notification list is empty', () => {
    cy.get('[data-testid="notification-bell"]').click();
    cy.get('[data-testid="empty-notification-message"]').should('be.visible');
    cy.get('[data-testid="notification-item"]').should('not.exist');
  });

  it('should close notification panel after navigation', () => {
    cy.get('[data-testid="notification-bell"]').click();
    cy.get('[data-testid="notification-list"]').should('be.visible');

    cy.get('[data-testid="notification-item"]').first().click();

    cy.get('[data-testid="notification-list"]').should('not.be.visible');
    cy.url().should('include', '/content');
  });

  it('should maintain notification state when navigating back', () => {
    cy.get('[data-testid="notification-bell"]').click();
    cy.get('[data-testid="notification-item"]').first().click();
    cy.url().should('include', '/content');

    cy.go('back');
    cy.url().should('not.include', '/content');

    cy.get('[data-testid="notification-bell"]').click();
    cy.get('[data-testid="notification-list"]').should('be.visible');
  });
});
